function renderRewards(ui, summary) {
  const items = Array.isArray(summary?.items) ? summary.items : [];
  const available = !!summary && !!(summary.title || summary.note || items.length);
  const key = available ? JSON.stringify([summary.title, items, summary.note, summary.kind]) : null;
  if (ui.rewardKey === key) return;
  ui.rewardKey = key;
  ui.reward.hidden = !available;
  if (!available) {
    write(ui.rewardTitle, '');
    write(ui.rewardNote, '');
    ui.rewardItems.replaceChildren();
    return;
  }
  ui.reward.dataset.kind = ['preview', 'awarded', 'claimed'].includes(summary.kind) ? summary.kind : 'preview';
  write(ui.rewardTitle, summary.title || '');
  ui.rewardTitle.hidden = !summary.title;
  ui.rewardItems.replaceChildren(...items.map(item => {
    const row = create('div');
    row.append(create('dt', '', item.label), create('dd', '', item.value));
    return row;
  }));
  ui.rewardItems.hidden = !items.length;
  write(ui.rewardNote, summary.note || '');
  ui.rewardNote.hidden = !summary.note;
}

function renderReview(ui, quiz, lesson, result, running, disabled) {
  const available = !!quiz && !running && reviewFailureStates.has(result?.status) && typeof lesson?.code === 'string' && lesson.code.length > 0;
  const explanation = available ? Array.isArray(lesson.explanation) ? lesson.explanation.join('\n') : String(lesson.explanation || '') : '';
  const key = available ? JSON.stringify([quiz.id, lesson.id, lesson.title, lesson.code, explanation]) : null;
  if (ui.reviewKey !== key) {
    ui.reviewKey = key;
    ui.reviewOpen = false;
    ui.review.hidden = true;
    ui.reviewToggle.setAttribute('aria-expanded', 'false');
    write(ui.reviewToggle, '写経した教材を見直す');
  }
  ui.reviewTools.hidden = !available;
  ui.reviewToggle.disabled = !!disabled;
  write(ui.reviewTitle, available ? lesson.title || '写経した教材' : '');
  write(ui.reviewExplanation, explanation);
  ui.reviewExplanation.hidden = !explanation;
  renderHighlightedCode(ui.reviewCode, available ? lesson.code : '', quiz?.language);
}

function renderProblemDetails(ui, quiz) {
  const constraints = Array.isArray(quiz?.constraints) ? quiz.constraints : [];
  const firstCase = quiz?.cases?.[0];
  const differentCase = firstCase && quiz.cases.find(test => JSON.stringify(test.expected) !== JSON.stringify(firstCase.expected));
  const examples = quiz?.language === 'sql' ? [] : Array.isArray(quiz?.examples) ? quiz.examples : [firstCase, differentCase].filter(Boolean);
  const key = JSON.stringify([quiz?.id, constraints, examples]);
  if (ui.problemKey === key) return;
  ui.problemKey = key;
  ui.constraintList.replaceChildren(...constraints.map(text => create('li', '', text)));
  ui.constraints.hidden = !constraints.length;
  ui.exampleList.replaceChildren(...examples.map(example => {
    const item = create('li');
    const input = create('dl', 'quiz-example-values');
    for (const [index, parameter] of (quiz.parameters || []).entries()) {
      const row = create('div');
      row.append(create('dt', '', parameter.name), create('dd', '', JSON.stringify(example.args[index])));
      input.append(row);
    }
    const output = create('div', 'quiz-example-result');
    output.append(create('span', '', '返り値'), create('code', '', JSON.stringify(example.expected)));
    item.append(input, output);
    if (example.explanation) item.append(create('p', 'quiz-example-explanation', example.explanation));
    return item;
  }));
  ui.examples.hidden = !examples.length;
}

function renderCases(ui, quiz, result, stale, running) {
  const results = Array.isArray(result?.cases) ? result.cases : Array.isArray(result?.results) ? result.results : [];
  const questionCases = quiz?.cases || [];
  const key = JSON.stringify([quiz?.id, questionCases, results, stale, running]);
  if (ui.caseKey === key) return;
  ui.caseKey = key;
  const entries = questionCases.map((test, index) => {
    const match = results.find(row => row.id === test.id || row.caseId === test.id) || results[index];
    const testStatus = stale || running ? 'idle' : caseStatus(match);
    const row = create('li', 'quiz-case');
    row.dataset.status = testStatus;
    const heading = create('div', 'quiz-case-heading');
    const status = create('span', 'quiz-case-status', testStatus === 'idle' ? '未実行' : successStates.has(testStatus) ? '成功' : labels[testStatus] || '不合格');
    heading.append(create('b', '', test.name || `ケース ${index + 1}`), status);
    const values = create('dl', 'quiz-case-values');
    const args = test.input ?? test.args ?? [];
    const sqlFixture = quiz?.language === 'sql' && Array.isArray(test.fixtureRows);
    const sqlScript = quiz?.language === 'sql' && typeof test.fixtureSql==='string';
    const sqlTables=quiz?.language==='sql' && Array.isArray(test.fixtureTables)?test.fixtureTables:sqlFixture?[{name:test.fixtureTable || quiz.fixtureTable || 'sample',columns:test.fixtureColumns || quiz.fixtureColumns || ['id','amount','group_id','enabled'],rows:test.fixtureRows}]:[];
    if (sqlTables.length) {
      const entry = create('div', 'quiz-fixture-input');
      const content = create('dd');
      for(const fixture of sqlTables){
      const table = create('table', 'quiz-fixture-table');
      const columns=fixture.columns;
      const tableName=fixture.name;
      table.append(create('caption', '', `${tableName}(${columns.join(', ')})`));
      const head = create('thead'), header = create('tr');
      for (const name of columns) {
        const cell = create('th', '', name);
        cell.scope = 'col';
        header.append(cell);
      }
      head.append(header);
      const body = create('tbody');
      for (const record of fixture.rows) {
        const line = create('tr');
        for (const value of record) line.append(create('td', '', textValue(value)));
        body.append(line);
      }
      table.append(head, body);
      content.append(table);
      }
      entry.append(create('dt', '', '入力DB'), content);
      values.append(entry);
    }
    if(sqlScript && !sqlTables.length){
      const entry=create('div','quiz-fixture-input'),content=create('dd');
      content.append(create('pre','quiz-fixture-sql',test.fixtureSql));entry.append(create('dt','','入力DB'),content);values.append(entry);
    }
    const pairs = [...(sqlTables.length || sqlScript ? [] : [['入力', args]]), ...(sqlFixture && quiz.topicId === 'recursive_counter' ? [['quiz_config.counter_limit', test.counterLimit]] : []), ['期待する結果', test.expected]];
    if (!stale && !running && match && ('actual' in match || 'output' in match)) pairs.push(['実際の結果', 'actual' in match ? match.actual : match.output]);
    for (const [label, value] of pairs) {
      const entry = create('div');
      entry.append(create('dt', '', label), create('dd', '', textValue(value)));
      values.append(entry);
    }
    row.append(heading, values);
    if (!stale && !running && match?.message) row.append(create('p', 'quiz-case-message', String(match.message).slice(0, 4000)));
    return row;
  });
  if (!entries.length) entries.push(create('li', 'quiz-case', 'この課題のテストケースは準備中です。'));
  // A question can have dozens of boundary cases. Keep a useful preview by the
  // editor and let the player expand the complete, unchanged test list.
  const failures = entries.filter(row => row.dataset.status && row.dataset.status !== 'idle' && !successStates.has(row.dataset.status));
  const preview = (failures.length ? failures : entries).slice(0, 3);
  const remaining = entries.filter(row => !preview.includes(row));
  ui.cases.replaceChildren(...preview);
  ui.moreCasesList.replaceChildren(...remaining);
  ui.moreCases.hidden = !remaining.length;
  write(ui.moreCasesLabel, `残り${remaining.length}件のテストケース`);
}

/**
 * Render a controlled Quiz panel without replacing its editor during game ticks.
 * Callbacks: onDraft(source), onRun(source), onCancel(), onNext(),
 * onSelect(index), onReference(isOpen), onOpenBook().
 * topics: [{index, title, completed, difficulty?, difficultyLabel?, available?, requiredLevel?, review?}], selectedIndex: number.
 * access: {available, requiredLevel, ownedLevel, bookName, reason, review}.
 * result: {status, cases:[{id, passed, actual, message}], message, diagnostics}.
 * A result.source differing from draft is displayed as stale, never as a pass.
 * progress: {phase:'download'|'prepare'|'compile'|'execute', loaded?, total?}.
 * reviewLesson: null or {title, code, explanation:string|string[]}; only the
 * caller's previously copied material for this topic, separate from its answer.
 * referenceAvailable: defaults to true; false keeps the answer locked and its
 * source out of the rendered code until the caller permits it after a pass.
 * rewardSummary: null or {title, items:[{label,value}], note,
 * kind:'preview'|'awarded'|'claimed'}; all calculations and wording are supplied
 * by the caller, including whether a previous result should remain visible.
 * No calls in this module award progress or evaluate the supplied source.
 */
export function renderQuizUI(options) {
  const { root, quiz, result = null, running = false, progress = null, disabled = false } = options;
  if (!root) throw new TypeError('Quiz panel root is required.');
  const ui = mounted.get(root) || mount(root);
  ui.model = options;
  const locked = options.access?.available === false;
  const key = quiz?.id ?? null;
  const changedQuestion = key !== ui.key;
  if (changedQuestion) {
    ui.key = key;
    ui.referenceOpen = false;
    ui.reference.hidden = true;
    ui.moreCases.open = false;
    ui.referenceToggle.setAttribute('aria-expanded', 'false');
    write(ui.referenceToggle, '解答例を見る');
  }
  const draft = String(options.draft ?? quiz?.starterSource ?? '');
  if (ui.editor.value !== draft) {
    const start = ui.editor.selectionStart, end = ui.editor.selectionEnd;
    const scrollTop = ui.editor.scrollTop, scrollLeft = ui.editor.scrollLeft;
    ui.editor.value = draft;
    if (!changedQuestion) {
      ui.editor.setSelectionRange(Math.min(start, draft.length), Math.min(end, draft.length));
      ui.editor.scrollTop = scrollTop;
      ui.editor.scrollLeft = scrollLeft;
    }
  }
  const beforeCursor = ui.editor.value.slice(0, ui.editor.selectionStart).split('\n');
  write(ui.cursor, `Ln ${beforeCursor.length}, Col ${beforeCursor.at(-1).length + 1}`);
  const stale = !!result && typeof result.source === 'string' && result.source !== draft;
  const resultStatus = locked ? 'locked' : stale ? 'stale' : result?.status || 'idle';
  const passed = !running && successStates.has(resultStatus);
  const results = result?.cases || result?.results || [];
  const successCount = results.filter(row => successStates.has(caseStatus(row))).length;
  const total = quiz?.cases?.length || results.length;
  const summary = successStates.has(resultStatus) || ['wrong-answer', 'fail', 'failed'].includes(resultStatus) ? `${labels[resultStatus]}${results.length ? ` · ${successCount} / ${total}件` : ''}` : labels[resultStatus] || '評価器のエラー';
  root.dataset.quizStatus = running ? 'running' : resultStatus;
  root.dataset.challengeAccess = locked ? 'locked' : options.access?.review ? 'review' : 'available';
  root.setAttribute('aria-busy', String(!!running));
  write(ui.title, quiz?.title || 'コードを実装して解く');
  write(ui.position, options.position ?? '');
  ui.position.hidden = !options.position;
  const topics = Array.isArray(options.topics) ? options.topics : [];
  const topicKey = JSON.stringify(topics);
  if (topicKey !== ui.topicKey) {
    ui.topicKey = topicKey;
    ui.topicSelect.replaceChildren(...topics.map(topic => {
      const option = create('option', '', `${topic.completed ? '✓ ' : ''}${topic.available===false ? '未解禁 · ' : ''}${topic.title}${topic.requiredLevel>0 ? ` · 教本 Lv.${topic.requiredLevel}` : ''}${topic.review ? ' · 復習可' : ''}`);
      option.value = String(topic.index);
      return option;
    }));
  }
  ui.topicPicker.hidden = !topics.length || typeof options.onSelect !== 'function';
  ui.topicSelect.disabled = !!disabled || !!running;
  if (options.selectedIndex !== undefined) ui.topicSelect.value = String(options.selectedIndex);
  const difficulties=[...new Set(topics.map(topic=>topic.difficulty).filter(Number.isInteger))].sort((a,b)=>a-b);
  const difficultyOptions=difficulties.map(level=>{
    const group=topics.filter(topic=>topic.difficulty===level),sample=group[0],available=group.filter(topic=>topic.available!==false).length;
    return {level,label:`${sample.difficultyLabel || `難度${level}`} · ${available}/${group.length}題に挑戦可${sample.requiredLevel>0 ? ` · 教本 Lv.${sample.requiredLevel}` : ''}`};
  });
  const difficultyKey=JSON.stringify(difficultyOptions);
  if(ui.difficultyKey!==difficultyKey){
    ui.difficultyKey=difficultyKey;
    ui.difficultySelect.replaceChildren(...difficultyOptions.map(({level,label})=>{
      const option=create('option','',label);option.value=String(level);return option;
    }));
  }
  ui.difficultyPicker.hidden=difficulties.length<2 || typeof options.onSelect!=='function';
  ui.difficultySelect.disabled=!!disabled || !!running;
  if(Number.isInteger(quiz?.difficulty))ui.difficultySelect.value=String(quiz.difficulty);
  ui.accessPanel.hidden=!locked;
  write(ui.accessReason,options.access?.reason || '必要な教本を確認してください。');
  ui.openBook.hidden=typeof options.onOpenBook!=='function';
  ui.openBook.disabled=!!disabled || !!running;
  write(ui.description, quiz?.description || '課題を選んでください。');
  const assessmentData=quiz?.assessment;
  const designAssessment='この課題では入出力の動作をテストします。クラスの分け方や設計全体の良し悪しは採点しません。';
  const contractAssessment=['state-contract','behavioral-contract'].includes(assessmentData?.kind);
  const assessment=typeof assessmentData==='string' ? assessmentData : contractAssessment ? [...(assessmentData.criteria || []).slice(0,2),...(assessmentData.limitations || []).slice(0,1)].filter(text=>typeof text==='string').join(' ') : quiz?.subject==='design' ? assessmentData?.limitations?.find(text=>typeof text==='string') || designAssessment : '';
  write(ui.assessment,assessment);ui.assessment.hidden=!assessment;
  const parameters = quiz?.parameters || [];
  const parametersKey = JSON.stringify(parameters);
  if (ui.parametersKey !== parametersKey) {
    ui.parametersKey = parametersKey;
    ui.parameters.replaceChildren(...parameters.map(parameter => {
      const entry = create('div');
      const name = typeof parameter === 'string' ? parameter : parameter.name;
      entry.append(create('dt', '', name), create('dd', '', typeof parameter === 'string' ? '' : parameter.description || parameter.type || ''));
      return entry;
    }));
  }
  ui.parameters.hidden = !parameters.length;
  renderProblemDetails(ui, quiz);
  ui.editor.disabled = !!disabled || !quiz;
  ui.editor.readOnly=locked;
  ui.run.disabled = !!disabled || !!running || locked || !quiz;
  write(ui.run, running ? '実行中…' : 'テストを実行');
  ui.cancel.hidden = !running || typeof options.onCancel !== 'function';
  ui.next.hidden = typeof options.onNext !== 'function' || !passed;
  ui.next.disabled = !!disabled || !!running;
  const referenceAvailable = !locked && options.referenceAvailable !== false && !!quiz?.referenceSource;
  ui.referenceToggle.hidden = !quiz?.referenceSource;
  ui.referenceToggle.disabled = !!disabled || !referenceAvailable;
  if (!referenceAvailable) ui.referenceOpen = false;
  ui.reference.hidden = !referenceAvailable || !ui.referenceOpen;
  ui.referenceToggle.setAttribute('aria-expanded', String(ui.referenceOpen));
  write(ui.referenceToggle, locked ? '解答例は課題の解禁・合格後に公開' : referenceAvailable ? ui.referenceOpen ? '解答例を閉じる' : '解答例を見る' : '解答例は合格後に公開');
  renderHighlightedCode(ui.referenceCode, referenceAvailable ? quiz.referenceSource : '', quiz?.language);
  const status = locked ? options.access?.reason || '教本で課題を解禁してください。' : running ? progressLabel(progress) : summary;
  write(ui.status, status);
  ui.status.dataset.kind = running ? 'running' : passed ? 'success' : errorStates.has(resultStatus) || ['fail', 'failed', 'wrong-answer'].includes(resultStatus) ? 'error' : 'neutral';
  ui.progress.hidden = !running;
  if (running && Number.isFinite(progress?.loaded) && Number.isFinite(progress?.total) && progress.total > 0) {
    ui.progress.max = progress.total;
    ui.progress.value = Math.min(progress.total, Math.max(0, progress.loaded));
  } else ui.progress.removeAttribute('value');
  const diagnosticRows = Array.isArray(result?.diagnostics) ? result.diagnostics : [];
  const diagnosticText = !stale && !running ? [result?.message || result?.error, ...diagnosticRows.map(row => {
    if (typeof row === 'string') return row;
    const line = row.line ?? row.lineNumber ?? row.location?.line;
    const column = row.column ?? row.columnNumber ?? row.location?.column;
    return [line ? `${line}行${column ? ` ${column}列` : ''}` : '', row.id || '', row.message || textValue(row)].filter(Boolean).join(' · ');
  })].filter(Boolean).join('\n').slice(0, 16000) : '';
  write(ui.diagnostics, diagnosticText);
  ui.diagnostics.hidden = !diagnosticText;
  renderRewards(ui, locked ? null : options.rewardSummary);
  renderReview(ui, quiz, locked ? null : options.reviewLesson, result, running, disabled);
  renderCases(ui, quiz, result, stale, running);
  ui.enhancedEditor.update({language: quiz?.language, context: (quiz?.parameters || []).map(parameter => parameter.name).join(' ')});
}

export function quizEditor(root) {
  return mounted.get(root)?.editor || null;
}
